function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'Excel' || !Array.isArray(args[0]) || args[0].length !== 2) return 'Start with Excel(height, width).';
  if (operations.length - 1 > 100) return 'At most 100 calls to set, get and sum.';
  const [height, width] = args[0];
  if (!Number.isInteger(height) || height < 1 || height > 26) return 'height is between 1 and 26.';
  if (typeof width !== 'string' || !/^[A-Z]$/.test(width)) return 'width is one capital letter from A to Z.';
  const inside = (row, column) => Number.isInteger(row) && row >= 1 && row <= height && typeof column === 'string' && /^[A-Z]$/.test(column) && column <= width;
  const formulas = new Map();
  const plain = new Map();
  for (let i = 1; i < operations.length; i++) {
    const [row, column, extra] = args[i] ?? [];
    if (!inside(row, column)) return 'Every cell must lie inside the sheet.';
    const cell = column + row;
    if (operations[i] === 'get') continue;
    if (operations[i] === 'set') {
      if (!Number.isInteger(extra) || extra < -100 || extra > 100) return 'set takes a value from -100 to 100.';
      formulas.delete(cell);
      plain.set(cell, extra);
    } else if (operations[i] === 'sum') {
      if (!Array.isArray(extra) || extra.length < 1 || extra.length > 5) return 'sum takes 1 to 5 references.';
      const counts = new Map();
      for (const ref of extra) {
        const match = typeof ref === 'string' && ref.match(/^([A-Z])([1-9]\d?)(?::([A-Z])([1-9]\d?))?$/);
        if (!match) return 'Each reference looks like "B3" or "B3:F7".';
        const [, c1, r1, c2 = c1, r2 = r1] = match;
        if (!inside(Number(r1), c1) || !inside(Number(r2), c2)) return 'References must lie inside the sheet.';
        if (c1 > c2 || Number(r1) > Number(r2)) return 'A range goes from its top-left to its bottom-right cell.';
        for (let r = Number(r1); r <= Number(r2); r++) for (let c = c1.charCodeAt(0); c <= c2.charCodeAt(0); c++) counts.set(String.fromCharCode(c) + r, (counts.get(String.fromCharCode(c) + r) ?? 0) + 1);
      }
      const stack = [...counts.keys()];
      const seen = new Set();
      while (stack.length) {
        const next = stack.pop();
        if (next === cell) return 'A formula cannot depend on its own cell.';
        if (seen.has(next)) continue;
        seen.add(next);
        for (const source of formulas.get(next)?.keys() ?? []) stack.push(source);
      }
      formulas.set(cell, counts);
    } else return 'Only set, get and sum can follow the constructor.';
    const memo = new Map();
    const value = (key) => {
      if (!formulas.has(key)) return plain.get(key) ?? 0;
      if (memo.has(key)) return memo.get(key);
      let total = 0;
      for (const [source, times] of formulas.get(key)) total += times * value(source);
      memo.set(key, total);
      return total;
    };
    for (const key of formulas.keys()) if (Math.abs(value(key)) > 2147483647) return 'Every cell value must fit in a 32-bit integer.';
  }
  return null;
}

