class Excel {
  constructor(height, width) {
    this.values = new Map();
    this.formulas = new Map();
    this.dependents = new Map();
  }

  set(row, column, val) {
    const cell = column + row;
    this.clearFormula(cell);
    this.values.set(cell, val);
    this.propagate(cell);
  }

  get(row, column) {
    return this.values.get(column + row) ?? 0;
  }

  sum(row, column, numbers) {
    const cell = column + row;
    this.clearFormula(cell);
    const counts = new Map();
    for (const part of numbers) {
      const [from, to = from] = part.split(':');
      for (let r = Number(from.slice(1)); r <= Number(to.slice(1)); r++) {
        for (let c = from.charCodeAt(0); c <= to.charCodeAt(0); c++) {
          const source = String.fromCharCode(c) + r;
          counts.set(source, (counts.get(source) ?? 0) + 1);
        }
      }
    }
    this.formulas.set(cell, counts);
    for (const source of counts.keys()) {
      if (!this.dependents.has(source)) this.dependents.set(source, new Set());
      this.dependents.get(source).add(cell);
    }
    this.propagate(cell);
    return this.values.get(cell);
  }

  clearFormula(cell) {
    for (const source of this.formulas.get(cell)?.keys() ?? []) this.dependents.get(source).delete(cell);
    this.formulas.delete(cell);
  }

  propagate(start) {
    const order = [];
    const visited = new Set([start]);
    const visit = (cell) => {
      for (const next of this.dependents.get(cell) ?? []) {
        if (visited.has(next)) continue;
        visited.add(next);
        visit(next);
      }
      order.push(cell);
    };
    visit(start);
    for (let i = order.length - 1; i >= 0; i--) {
      const counts = this.formulas.get(order[i]);
      if (!counts) continue;
      let total = 0;
      for (const [source, times] of counts) total += times * (this.values.get(source) ?? 0);
      this.values.set(order[i], total);
    }
  }
}

