class Excel {
  constructor(height, width) {
    this.grid = Array.from({ length: height + 1 }, () => Array.from({ length: 26 }, () => ({ value: 0, refs: null })));
  }
  set(row, column, val) {
    this.grid[row][column.charCodeAt(0) - 65] = { value: val, refs: null };
  }
  get(row, column) {
    return this.evaluate(row, column.charCodeAt(0) - 65, new Map());
  }
  sum(row, column, numbers) {
    this.grid[row][column.charCodeAt(0) - 65] = { value: 0, refs: numbers.slice() };
    return this.get(row, column);
  }
  // Recompute from scratch on every read, expanding each listed reference again.
  evaluate(row, col, memo) {
    const entry = this.grid[row][col];
    if (!entry.refs) return entry.value;
    const key = row * 26 + col;
    if (memo.has(key)) return memo.get(key);
    let total = 0;
    for (const ref of entry.refs) {
      const ends = ref.split(':');
      const first = ends[0], last = ends[ends.length - 1];
      for (let r = parseInt(first.slice(1), 10); r <= parseInt(last.slice(1), 10); r++)
        for (let c = first.charCodeAt(0) - 65; c <= last.charCodeAt(0) - 65; c++) total += this.evaluate(r, c, memo);
    }
    memo.set(key, total);
    return total;
  }
}

