function generate(rand, size) {
  const large = size === 'large';
  const pick = (n) => Math.floor(rand() * n);
  const height = large ? 26 : 1 + pick(4);
  const lastCol = large ? 25 : pick(4);
  const letter = (c) => String.fromCharCode(65 + c);
  const calls = large ? 100 : 1 + pick(10);
  const operations = ['Excel'];
  const args = [[height, letter(lastCol)]];
  const formulas = new Map();
  const plain = new Map();
  // Does any cell in `starts` use `target`, directly or through other formulas?
  const reaches = (starts, target) => {
    const stack = [...starts];
    const seen = new Set();
    while (stack.length) {
      const cell = stack.pop();
      if (cell === target) return true;
      if (seen.has(cell)) continue;
      seen.add(cell);
      for (const source of formulas.get(cell)?.keys() ?? []) stack.push(source);
    }
    return false;
  };
  // Keep every value inside the 32-bit range.
  const fits = () => {
    const memo = new Map();
    const value = (cell) => {
      if (!formulas.has(cell)) return plain.get(cell) ?? 0;
      if (memo.has(cell)) return memo.get(cell);
      let total = 0;
      for (const [source, times] of formulas.get(cell)) total += times * value(source);
      memo.set(cell, total);
      return total;
    };
    for (const cell of formulas.keys()) if (Math.abs(value(cell)) > 1e9) return false;
    return true;
  };
  while (operations.length <= calls) {
    const row = 1 + pick(height);
    const col = pick(lastCol + 1);
    const cell = letter(col) + row;
    const kind = rand();
    if (kind < 0.3) {
      operations.push('get');
      args.push([row, letter(col)]);
      continue;
    }
    const oldFormula = formulas.get(cell);
    const oldPlain = plain.get(cell);
    const restore = () => {
      if (oldFormula) formulas.set(cell, oldFormula); else formulas.delete(cell);
      if (oldPlain === undefined) plain.delete(cell); else plain.set(cell, oldPlain);
    };
    if (kind < 0.6) {
      const val = rand() < 0.15 ? (rand() < 0.5 ? -100 : 100) : pick(201) - 100;
      formulas.delete(cell);
      plain.set(cell, val);
      if (!fits()) { restore(); continue; }
      operations.push('set');
      args.push([row, letter(col), val]);
      continue;
    }
    const numbers = [];
    const counts = new Map();
    const parts = 1 + pick(large ? 5 : 3);
    const existing = [...formulas.keys()];
    for (let i = 0; i < parts; i++) {
      if (existing.length && rand() < 0.4) {
        const used = existing[pick(existing.length)];
        numbers.push(used);
        counts.set(used, (counts.get(used) ?? 0) + 1);
        continue;
      }
      const top = 1 + pick(height);
      const bottom = top + pick(Math.min(height - top + 1, large ? 6 : 3));
      const left = pick(lastCol + 1);
      const right = left + pick(Math.min(lastCol - left + 1, large ? 6 : 3));
      const single = top === bottom && left === right && rand() < 0.7;
      numbers.push(single ? letter(left) + top : letter(left) + top + ':' + letter(right) + bottom);
      for (let r = top; r <= bottom; r++) for (let c = left; c <= right; c++) counts.set(letter(c) + r, (counts.get(letter(c) + r) ?? 0) + 1);
    }
    if (reaches(counts.keys(), cell)) continue;
    formulas.set(cell, counts);
    if (!fits()) { restore(); continue; }
    operations.push('sum');
    args.push([row, letter(col), numbers]);
  }
  return [operations, args];
}
